PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?a ?ce ?in ?s WHERE { ?s a ex:Person . ?s ex:age ?a . FILTER (!bound(?e)) ?s ^ex:knows ?in . BIND (COALESCE(?e, "none") AS ?ce) }

PREFIX ex: <http://example.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?a ?o ?os ?s WHERE { ?s ex:age ?a . ?s ex:knows ?o . MINUS { ?s a ex:Admin } OPTIONAL { { ?s ex:score ?os FILTER (?os > 5) } } }

PREFIX ex: <http://example.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?fn ?o ?s WHERE { ?s ex:knows ?o . ?s ex:knows/ex:name ?fn . FILTER (!bound(?e)) }

PREFIX ex: <http://example.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?a ?a2 ?s WHERE { ?s ex:age ?a . OPTIONAL { ?s ex:age ?a2 FILTER (?a2 > 20) } FILTER (?a > 20) FILTER (?a = 30 || ?a = 41) }
